  async function getIcon(name) {
    if (!Object.hasOwn(icons, name)) return '';
    const value = icons[name];
    return { path: value[4], viewBox: value.slice(0, 4).join(' ') };
  }
  async function getIconList() { return Object.keys(icons).map((name) => ({ name })); }
  window.customIconsets = window.customIconsets || {};
  window.customIconsets.phu = getIcon;
  window.customIcons = window.customIcons || {};
  window.customIcons.phu = { getIcon, getIconList };
